import pyotp
import pytest

from app.auth import AuthError, get_session, login, otp_header

ALICE_SECRET = "JBSWY3DPEHPK3PXP"
BOB_SECRET = "KRSXG5CTMVRXEZLU"


def _otp(secret: str) -> str:
    return pyotp.TOTP(secret).now()


def test_login_correcto_abre_sesion():
    s = login("alice", "alice-pass", _otp(ALICE_SECRET))
    assert s.username == "alice"
    assert get_session(s.token) == s


def test_login_incorrecto():
    with pytest.raises(AuthError):
        login("alice", "mal", _otp(ALICE_SECRET))
    with pytest.raises(AuthError):
        login("nadie", "alice-pass", _otp(ALICE_SECRET))


def test_login_otp_incorrecto_o_vacio():
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "000000")
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "")


def test_login_sin_otp_falla():
    with pytest.raises(TypeError):
        login("alice", "alice-pass")


def test_login_otp_sustituible_con_monkeypatch(monkeypatch):
    monkeypatch.setattr("app.auth.verificar_otp", lambda username, code: True)
    s = login("alice", "alice-pass", "codigo-cualquiera")
    assert s.username == "alice"


def test_otp_header_existe_como_dependencia_fastapi():
    from fastapi import Depends, FastAPI
    from fastapi.testclient import TestClient

    app = FastAPI()

    @app.get("/echo-otp")
    def echo_otp(otp: str = Depends(otp_header)):
        return {"otp": otp}

    c = TestClient(app)
    assert c.get("/echo-otp").json() == {"otp": ""}
    assert c.get("/echo-otp", headers={"X-OTP": "123456"}).json() == {"otp": "123456"}
    assert "X-OTP" in (otp_header.__doc__ or "")


def test_endpoint_login(client):
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass", "otp": _otp(BOB_SECRET)}
    ).status_code == 200
    assert client.post(
        "/login", json={"username": "bob", "password": "x", "otp": _otp(BOB_SECRET)}
    ).status_code == 401


def test_endpoint_login_sin_otp_o_con_otp_invalido(client):
    assert (
        client.post("/login", json={"username": "bob", "password": "bob-pass"}).status_code
        == 401
    )
    assert (
        client.post(
            "/login", json={"username": "bob", "password": "bob-pass", "otp": "000000"}
        ).status_code
        == 401
    )

